code='''def transform(grid):
    h = len(grid)
    out = [[0] * 7 for _ in range(h)]
    marker = next(( (r, c - 8) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5), (0, 0))
    y, x = marker
    out[y][x] = 5
    bands = range(0, h - 2, 4)
    tiles = []
    for c0 in (0, 4):
        for r0 in bands:
            cells = [(i, j, grid[r0+i][c0+j]) for i in range(3) for j in range(3) if grid[r0+i][c0+j] not in (0, 4, 5)]
            if not cells:
                continue
            color = cells[0][2]
            pat = tuple(tuple(grid[r0+i][c0+j] for j in range(3)) for i in range(3))
            if color == 1:
                direction, length = 'R', 3
            elif color == 2:
                direction, length = 'L', 2
            elif color == 6:
                direction, length = 'D', 2
            elif color == 3:
                direction, length = 'L', 4
            else:
                continue
            tiles.append((direction, length, color, pat))
    previous = None
    for direction, length, color, pat in tiles:
        # Repeated adjacent glyphs still advance the route, but their duplicate stroke is suppressed.
        suppress = previous == (direction, length, color, pat)
        if direction == 'D':
            if not suppress:
                for r in range(y + 1, y + length + 1):
                    if r < h and 0 <= x < 7:
                        out[r][x] = color
            y += length
        else:
            r = y + 1
            xs = range(x, x + length) if direction == 'R' else range(x - length + 1, x + 1)
            if not suppress:
                for c in xs:
                    if r < h and 0 <= c < 7:
                        out[r][c] = color
            x = x + length - 1 if direction == 'R' else x - length + 1
            y += 1
        previous = (direction, length, color, pat)
    return out
